// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MockERC20 token;
    ERC1271Maker maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new MockERC20();
        maker = new ERC1271Maker();
        maker.approveToken(address(token), address(c));
    }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce,
        uint256 expiration,
        bytes memory signature
    ) public {
        vm.assume(signature.length < 200);
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 9_999 days);
        nonce = bound(nonce, 0, 1e30);
        vm.warp(1_000_000);
        expiration = bound(expiration, block.timestamp + 1, block.timestamp + 1e9);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bool ok;
        try c.fillOrder(order, signature, floorAssetTokenIds) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "a valid, signed, uncancelled, unexpired order must be fillable");
    }
}

contract ERC1271Maker {
    function approveToken(address token, address spender) external {
        MockERC20(token).approve(spender, type(uint256).max);
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}
